package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addDays_TriageGen2Test {

    @Test
    public void testAddDaysPositive() {
        // Test adding a positive number of days
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);
        dt.addDays(5);
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(6, dt.getDayOfMonth());
    }

    @Test
    public void testAddDaysNegative() {
        // Test adding a negative number of days (subtracting)
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        dt.addDays(-5);
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(5, dt.getDayOfMonth());
    }

    @Test
    public void testAddDaysZero() {
        // Test adding zero days
        MutableDateTime dt = new MutableDateTime(2023, 5, 20, 10, 30, 0, 0);
        long originalMillis = dt.getMillis();
        dt.addDays(0);
        assertEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDaysCrossingMonthBoundary() {
        // Test adding days that move from one month to the next
        MutableDateTime dt = new MutableDateTime(2023, 1, 30, 12, 0, 0, 0);
        dt.addDays(2);
        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddDaysCrossingYearBoundary() {
        // Test adding days that move from one year to the next
        MutableDateTime dt = new MutableDateTime(2023, 12, 31, 23, 59, 59, 0);
        dt.addDays(1);
        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddDaysLeapYear() {
        // Test leap year handling
        MutableDateTime dt = new MutableDateTime(2024, 2, 28, 12, 0, 0, 0);
        dt.addDays(1);
        assertEquals(29, dt.getDayOfMonth());
        assertEquals(2, dt.getMonthOfYear());

        dt.addDays(1);
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddDaysLargeValue() {
        // Test adding a very large number of days
        MutableDateTime dt = new MutableDateTime(2000, 1, 1, 0, 0, 0, 0);
        dt.addDays(365 * 10); // Roughly 10 years
        // Validating that the year has advanced significantly
        assertTrue(dt.getYear() >= 2010);
    }
}
